from collections import Counter, deque

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [list(row) for row in grid]

    # Count colors
    counts = Counter()
    for row in grid:
        counts.update(row)

    if not counts:
        return grid

    # Identify colors: most common = bg, least = obj, middle = border
    if len(counts) < 3:
        return grid

    colors = sorted(counts.items(), key=lambda x: x[1])
    bg_color = colors[-1][0]
    obj_color = colors[0][0]
    border_color = colors[1][0]

    # Flood fill from edges to mark outside pixels
    visited = [[False]*cols for _ in range(rows)]
    queue = deque()

    # Start from all edge pixels (that aren't border)
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                if grid[r][c] != border_color:
                    visited[r][c] = True
                    queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] != border_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Apply transformations to pixels that are NOT visited (inside)
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != border_color:
                if grid[r][c] == bg_color:
                    output[r][c] = obj_color
                elif grid[r][c] == obj_color:
                    output[r][c] = 4

    return output
