def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Count colors
    counts = {}
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    # Sort by frequency: bg (most), border (middle-ish), obj (least)
    colors = sorted(counts.items(), key=lambda x: x[1], reverse=True)

    bg_color = colors[0][0]       # Most frequent (5)
    obj_color = colors[-1][0]     # Least frequent (9)
    border_color = colors[1][0]   # Middle frequency (6)

    # Find starting positions (border pixels)
    border_positions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == border_color:
                border_positions.append((r, c))

    if not border_positions:
        return grid

    # BFS to find all "interior" pixels reachable from border (not border itself)
    # This finds regions "inside" the border structure
    inside = [[False] * cols for _ in range(rows)]

    # Start BFS from border pixels
    queue = deque(border_positions)

    while queue:
        r, c = queue.popleft()

        # Check 4 neighbors
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if not inside[nr][nc] and grid[nr][nc] != border_color:
                    inside[nr][nc] = True
                    queue.append((nr, nc))

    # Create output grid
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Apply transformations to "inside" pixels
    for r in range(rows):
        for c in range(cols):
            if inside[r][c]:  # If this pixel is reachable from border (interior)
                if grid[r][c] == bg_color:
                    output[r][c] = obj_color  # Background becomes object color
                elif grid[r][c] == obj_color:
                    output[r][c] = 4          # Objects become 4
                # Border stays same

    return output
